source("pre.R")
cat("--- int64\n")
i <- zuint::int64(c("1", "9007199254740993", NA, "-5", "1")); print(class(i)); print(attributes(i))
x <- try_(zutable(i = i, v = 1:5)); print(x); print(schema(x))
both(x[by = i, select = .(n = .N)]); print(as.data.frame(x[by = i, select = .(n = .N)]))
print(try_(x[order = i])); print(try_(x[i > 1])); print(try_(x[select = .(f = first(i), c = count(i))])); print(try_(x[select = .(.all, c = coalesce(i, i))]))
both(x[distinct = TRUE, select = .(i)]); print(x[distinct = TRUE, select = .(i)])
both(join(x, x, on = i, suffix = c("", "2"))); print(as.data.frame(join(x, x, on = i, suffix = c("", "2"), na_equal = FALSE)))
print(na(int64)); print(class(na(int64))); x2 <- try_(zutable(a = 1:2, b = na(int64))); print(x2)
try_({x$i <- NA; print(x)}); try_({x[1, "i"] <- zuint::int64("7"); print(x)}); try_(x[, i := 7L]); try_(x[, i := 7]); print(rbind(x, x)$i)
print(x[c(1, NA)]); print(x[2:3]$i)
cat("--- decimal\n")
d <- decimal::as_decimal(c("1.50", "2.25", NA, "-0.10")); print(class(d)); print(attributes(d)); print(unclass(d))
y <- try_(zutable(d = d, v = 1:4)); print(y); print(schema(y))
both(y[by = d, select = .(n = .N)]); print(try_(y[order = d])); print(try_(y[d > 1])); both(y[distinct = TRUE, select = .(d)])
print(try_(as_zutable(data.frame(v = 1:2), schema(v = int32, d = decimal(5, 2)))))
print(na(decimal(5, 2))); y2 <- try_(zutable(a = 1:2, b = na(decimal(5, 2)))); print(y2); print(schema(y2))
dd <- decimal::as_decimal(c("1.5", "22.25")); print(attributes(dd)); print(try_(schema(zutable(d = dd)))); 
print(try_(conform(zutable(d = dd), schema(d = decimal(3, 2))))); print(try_(conform(zutable(d = dd), schema(d = decimal(38, 2)))))
big <- try_(decimal::as_decimal("1e400")); print(try_(schema(zutable(d = big)))); print(try_(schema(zutable(d = decimal::as_decimal(c("NaN", "Infinity"))))))
print(try_(schema(zutable(d = decimal::as_decimal("1E+3"))))); print(unclass(decimal::as_decimal("1E+3"))); print(try_(schema(zutable(d = decimal::as_decimal("0.000"))))); print(try_(schema(zutable(d = decimal::as_decimal(c("1.5", "1.25")))))); print(attributes(decimal::as_decimal(c("1.5", "1.25"))))
cat("--- struct / list / binary\n")
s <- zutable(id = 1:3, st = data.frame(a = c(1L, NA, NA), b = c("x", NA, "z")), l = list(1:2, NULL, integer()), bin = list(as.raw(1), NULL, raw()))
print(s[select = .(id, n1 = is.na(st), n2 = is.na(l), n3 = is.na(bin))]); print(try_(s[select = .(c = count(st), cl = count(l), cb = count(bin))])); both(s[select = .(c = count(st), cl = count(l), cb = count(bin))])
both(s[select = .(f = first(st), la = last(l), fb = first(bin))]); both(s[id > 1]); both(s[order = desc(id)]); print(try_(s[distinct = TRUE]))
print(try_(s[by = id, select = .(f = first(st), l2 = last(l))])); both(s[by = id, select = .(f = first(st), l2 = last(l))])
print(try_(s[select = .(c = coalesce(st, st), i = ifelse(id > 1L, l, l))]))
print(try_(s[c(1, NA)])); str(as.data.frame(s[c(3, NA)]))
try_({s$l <- list(1L, 2L, "a"); print(s)}); try_({s$l[[2]] <- 5L; print(s$l)}); try_({s[2, "st"] <- data.frame(a = 9L, b = "q"); print(as.data.frame(s))}); try_({s$st$a <- c(1.5, 2, 3); print(s)}); try_(print(s))
print(try_(zutable(st = data.frame(a = 1:2, a2 = I(list(1, 2))))))
print(try_(zutable(st = data.frame())))
print(try_(zutable(a = 1:3, st = data.frame(a = 1))))
print(na(struct(a = int32, b = list(string)))); print(na(list(int32))); print(na(enum(c("a")))); print(try_(na(r_class("foo")))); print(try_(na(timestamp("ns")))); print(na(timestamp("s", "Asia/Tokyo"))); print(try_(na()))
print(try_(zutable(a = 1:2, e = na(enum(c("lo", "hi"))), t = na(timestamp), dt = na(date), st = na(struct(a = int32)))))
cat("--- extension\n")
print(try_(register_extension_type("example.celsius", structure(double(), class = "celsius"), float64)))
ce <- structure(c(1.5, NA), class = "celsius"); z <- try_(zutable(t = ce, i = 1:2)); print(schema(z)); print(try_(z[i > 1])); print(try_(z[c(2, NA)]$t)); print(try_(z[order = t])); print(na(extension("example.celsius")))
print(try_(register_extension_type("x", double(), float64))); print(try_(register_extension_type(c("a", "b"), ce[0], float64))); print(try_(register_extension_type("x", ce[0], "nonsense")))
cat("--- r(), case, ifelse\n")
w <- zutable(a = c(1L, NA, 3L), b = c(1.5, 2.5, NA), s = c("x", "y", NA))
print(try_(w[select = .(r1 = r(a * 2L, int32), r2 = r(paste(s, a), string), r3 = r(1, float64), r4 = r(nchar(s), int32))]))
print(try_(w[select = .(r1 = r(a * 2, int32))])); print(try_(w[select = .(r1 = r(a[1:2], int32))])); print(try_(w[r(a > 1, bool)])); print(try_(w[by = s, select = .(m = r(sum(a), int32))]))
print(try_(w[select = .(c1 = case(a > 1L ~ "big", is.na(a) ~ "none", .default = "small"), c2 = case(a > 1L ~ 1), c3 = case(a > 1L ~ b, .default = 0), c4 = ifelse(a > 1L, 1, 2.5), c5 = ifelse(is.na(a), NA, a), c6 = coalesce(a, 0L), c7 = coalesce(b, a))]))
print(try_(w[select = .(c4 = ifelse(a > 1L, 1L, 2.5))])); print(try_(w[select = .(c4 = ifelse(a > 1L, 2.5, 1L))])); print(try_(w[select = .(c = case(a > 1L ~ 1L, .default = 2.5))])); print(try_(w[select = .(c = coalesce(a, 0.5))])); print(try_(w[select = .(c = a + 0.5, d = a == 1.5, e = a %in% c(1, 3), f = b %in% 1:3, g = between(a, 1, 2.5), h = between(b, 1L, 3L))]))
print(try_(w[select = .(c = a %in% c(1.5))])); print(try_(w[select = .(c = a %in% c(1, NA))])); print(try_(w[select = .(c = a %in% integer())])); print(try_(w[select = .(c = s %in% character(), d = !(s %in% "x"))])); print(try_(w[select = .(c = a %in% NULL)]))
